def parse_assignment(line: str) -> tuple[str, str]:
    if "=" not in line:
        raise ValueError("missing '=' separator")
    key, value = line.split("=", 1)
    key = key.strip()
    value = value.strip()
    if not key:
        raise ValueError("empty key")
    return key, value


